USE novacart;

SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
SET SESSION sql_mode = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM notifications;
DELETE FROM coupon_usage;
DELETE FROM reviews;
DELETE FROM payments;
DELETE FROM wishlist;
DELETE FROM order_items;
DELETE FROM orders;
DELETE FROM cart_items;
DELETE FROM carts;
DELETE FROM product_images;
DELETE FROM products;
DELETE FROM user_addresses;
DELETE FROM categories;
DELETE FROM coupons;
DELETE FROM users;

SET FOREIGN_KEY_CHECKS = 1;

START TRANSACTION;





SELECT id, CONCAT('/assets/products/', slug, '-front.webp'), CONCAT(name, ' front view'), 1200, 1200, 10, 1, created_at FROM products;

SELECT id, CONCAT('/assets/products/', slug, '-detail.webp'), CONCAT(name, ' detail view'), 1200, 1200, 20, 0, created_at FROM products;











COMMIT;
