(1, 1, 'NC-AUD-1001', 'wireless-noise-cancelling-headphones', 'Wireless Noise Cancelling Headphones', 'Auralux', 'Immersive sound with adaptive active noise cancellation and 40-hour battery.', 'Studio-tuned 40mm drivers, adaptive noise cancellation, plush memory-foam earcups and fast USB-C charging make these headphones comfortable through long listening sessions.', 4999.00, 7999.00, 34, 10, 4.80, 1284, 'Best Seller', 1, 1, 'active', 'headphones', '#2563EB', JSON_ARRAY('Adaptive ANC', '40-hour battery', 'Low-latency mode', 'Multipoint pairing', 'Foldable design'), JSON_OBJECT('Driver', '40mm dynamic', 'Battery life', '40 hours', 'Charging', 'USB-C fast charge', 'Bluetooth', '5.3', 'Weight', '254g'), JSON_ARRAY('audio', 'wireless', 'noise-cancelling'), 'Ships in 2-4 business days. Free delivery on orders above INR 999.', '2026-06-01 10:00:00.000000'),
(2, 1, 'NC-AUD-1002', 'portable-bluetooth-speaker', '360 Portable Bluetooth Speaker', 'Auralux', 'Room-filling 360-degree sound with a rugged waterproof build and 24-hour playtime.', 'A palm-sized speaker with a 20W driver, IPX7 waterproof shell, stereo pairing and a built-in microphone for calls.', 1999.00, 3499.00, 120, 15, 4.60, 862, NULL, 0, 1, 'active', 'speaker', '#3B82F6', JSON_ARRAY('360-degree audio', 'IPX7 waterproof', '24-hour playtime', 'Stereo pairing', 'Built-in microphone'), JSON_OBJECT('Output', '20W', 'Battery life', '24 hours', 'Waterproof', 'IPX7', 'Bluetooth', '5.3', 'Weight', '620g'), JSON_ARRAY('audio', 'bluetooth', 'portable'), 'Ships in 2-4 business days. Free delivery on orders above INR 999.', '2026-06-02 10:00:00.000000'),
(3, 1, 'NC-CAM-1003', '4k-mirrorless-camera', '4K Mirrorless Camera', 'Lumina', 'A 24.2MP sensor, 4K video and five-axis stabilisation in a compact body.', 'A compact APS-C mirrorless camera with crisp stills, smooth 4K video, in-body stabilisation and touch autofocus for creators on the move.', 64999.00, 79999.00, 12, 5, 4.70, 312, 'Premium', 1, 0, 'active', 'camera', '#64748B', JSON_ARRAY('24.2MP APS-C', '4K 30fps video', 'Five-axis stabilisation', 'Touchscreen autofocus', 'Wi-Fi and app'), JSON_OBJECT('Sensor', '24.2MP APS-C CMOS', 'Video', '4K at 30fps', 'Stabilisation', 'Five-axis in-body', 'Card slot', 'SD UHS-II', 'Battery', 'About 450 shots'), JSON_ARRAY('camera', '4k', 'creator'), 'Ships in 3-5 business days with insured delivery.', '2026-06-03 10:00:00.000000'),
(4, 2, 'NC-APP-2001', 'premium-organic-cotton-tshirt', 'Premium Organic Cotton T-Shirt', 'Everyday Co.', 'Soft combed cotton with a clean athletic cut in six colours.', 'A wardrobe staple made from 210 GSM organic combed cotton with a tailored athletic fit that holds its shape after every wash.', 799.00, 1299.00, 240, 20, 4.50, 2156, NULL, 0, 0, 'active', 'tshirt', '#9333EA', JSON_ARRAY('210 GSM combed cotton', 'Athletic fit', 'Pre-shrunk', 'Six colours', 'OEKO-TEX certified'), JSON_OBJECT('Material', '100% combed cotton', 'Weight', '210 GSM', 'Fit', 'Athletic', 'Sizes', 'S-XL', 'Care', 'Machine wash cold'), JSON_ARRAY('apparel', 'cotton', 'casual'), 'Ships in 2-4 business days. Free delivery on orders above INR 999.', '2026-06-04 10:00:00.000000'),
(5, 2, 'NC-FTW-2002', 'urban-comfort-sneakers', 'Urban Comfort Sneakers', 'Stridewell', 'Feather-light knit sneakers with cloud-soft cushioning for all-day comfort.', 'Breathable knit uppers, responsive foam and a grippy rubber outsole create a lightweight sneaker designed for commuting and weekends.', 3499.00, 5999.00, 86, 12, 4.60, 934, 'New', 1, 0, 'active', 'sneaker', '#7C3AED', JSON_ARRAY('Breathable knit', 'Cloud-foam midsole', 'Grippy outsole', 'Lightweight', 'Unisex sizing'), JSON_OBJECT('Upper', 'Engineered knit', 'Midsole', 'EVA cloud foam', 'Outsole', 'Rubber', 'Weight', '270g', 'Sizes', 'UK 6-11'), JSON_ARRAY('footwear', 'sneaker', 'sports'), 'Ships in 2-4 business days. Free delivery on orders above INR 999.', '2026-06-05 10:00:00.000000'),
(6, 2, 'NC-ACC-2003', 'aviator-polarised-sunglasses', 'Aviator Polarised Sunglasses', 'Solace', 'Classic aviator frames with polarised lenses and UV400 protection.', 'Feather-light metal frames hold polarised UV400 lenses that cut glare and improve contrast in bright conditions.', 1499.00, 2999.00, 65, 10, 4.40, 447, NULL, 0, 1, 'active', 'sunglasses', '#F59E0B', JSON_ARRAY('Polarised lenses', 'UV400 protection', 'Feather-light frame', 'Protective case', 'Anti-scratch coating'), JSON_OBJECT('Lenses', 'Polarised polycarbonate', 'Protection', 'UV400', 'Frame', 'Stainless steel', 'Weight', '24g', 'In box', 'Case and cloth'), JSON_ARRAY('eyewear', 'summer', 'accessory'), 'Ships in 2-4 business days. Free delivery on orders above INR 999.', '2026-06-06 10:00:00.000000'),
(7, 3, 'NC-GAM-3001', 'wireless-gaming-controller', 'Wireless Gaming Controller', 'Vector Play', 'Low-latency wireless control with textured grips and remappable buttons.', 'Hall-effect triggers, adaptable stick sensitivity and saved profiles support PC, console and mobile play.', 3299.00, 4999.00, 73, 10, 4.70, 1287, 'Best Seller', 1, 0, 'active', 'controller', '#4F46E5', JSON_ARRAY('Low-latency wireless', 'Remappable buttons', 'Hall-effect triggers', '20-hour battery', 'Multi-platform'), JSON_OBJECT('Connectivity', 'Bluetooth and 2.4GHz', 'Battery', '20 hours', 'Trigger', 'Hall-effect', 'Compatibility', 'PC, console, mobile', 'Extra buttons', '2 remappable'), JSON_ARRAY('gaming', 'controller', 'pc'), 'Ships in 2-4 business days. Free delivery on orders above INR 999.', '2026-06-07 10:00:00.000000'),
(8, 3, 'NC-GAM-3002', 'rgb-mechanical-keyboard', 'RGB Mechanical Keyboard', 'Vector Play', 'Hot-swappable brown switches with per-key RGB and a sturdy aluminium plate.', 'Pre-lubed tactile switches, a solid aluminium top plate and onboard lighting profiles create a dependable typing and gaming setup.', 4499.00, 6999.00, 41, 10, 4.60, 864, 'Trending', 1, 1, 'active', 'keyboard', '#8B5CF6', JSON_ARRAY('Hot-swappable', 'Pre-lubed brown switches', 'Per-key RGB', 'Aluminium plate', 'Double-shot keycaps'), JSON_OBJECT('Switches', 'Hot-swap brown', 'Layout', 'TKL 87-key', 'Backlight', 'Per-key RGB', 'Body', 'Aluminium and ABS', 'Connection', 'Wired USB-C'), JSON_ARRAY('gaming', 'keyboard', 'rgb'), 'Ships in 2-4 business days. Free delivery on orders above INR 999.', '2026-06-08 10:00:00.000000'),
(9, 4, 'NC-MOB-4001', 'novaphone-pro-5g', 'NovaPhone Pro 5G', 'NovaTech', 'Flagship 6.7-inch 120Hz AMOLED, 200MP camera and 5000mAh fast-charging battery.', 'A flagship smartphone with an LTPO display, triple camera system, rapid charging and long security support.', 32999.00, 41999.00, 58, 8, 4.80, 3021, 'Flagship', 1, 0, 'active', 'smartphone', '#0EA5E9', JSON_ARRAY('6.7-inch 120Hz AMOLED', '200MP camera', '5000mAh battery', '120W charging', '5G and Wi-Fi 7', 'Stereo speakers'), JSON_OBJECT('Display', '6.7-inch LTPO AMOLED 120Hz', 'Camera', '200MP + 50MP + 12MP', 'Battery', '5000mAh 120W', 'Chipset', 'Octa-core 4nm', 'Storage', '256GB UFS 4.0'), JSON_ARRAY('smartphone', '5g', 'flagship'), 'Ships in 1-3 business days with delivery tracking.', '2026-06-09 10:00:00.000000'),
(10, 4, 'NC-PWR-4002', 'titan-power-bank-20000mah', 'Titan Power Bank 20000mAh', 'NovaTech', '20W fast charging, dual output and a clear digital battery display.', 'A 20000mAh portable charger with USB-C and USB-A outputs, a digital remaining-capacity display and pass-through charging.', 1799.00, 2699.00, 145, 15, 4.50, 1560, NULL, 0, 0, 'active', 'powerbank', '#0284C7', JSON_ARRAY('20000mAh capacity', '20W fast charging', 'Dual output', 'Digital display', 'Pass-through charging'), JSON_OBJECT('Capacity', '20000mAh Li-Po', 'Output', 'USB-C 20W and USB-A 18W', 'Input', 'USB-C 18W', 'Display', 'LED digital', 'Weight', '410g'), JSON_ARRAY('power', 'mobile', 'travel'), 'Ships in 2-4 business days. Free delivery on orders above INR 999.', '2026-06-10 10:00:00.000000'),
