(12, 5, 'NC-LAP-5002', 'novabook-air-13', 'NovaBook Air 13', 'NovaTech', 'A feather-light 13.3-inch fanless laptop built for commuting.', 'A 980g fanless laptop with a sharp 2.5K display, instant-wake performance and a battery designed for long travel days.', 74999.00, 91999.00, 22, 5, 4.80, 398, NULL, 0, 1, 'active', 'laptop', '#818CF8', JSON_ARRAY('13.3-inch 2.5K display', '980g body', 'Fanless and silent', 'Instant wake', '18-hour battery'), JSON_OBJECT('Display', '13.3-inch 2.5K IPS', 'CPU', '8-core 4nm', 'RAM', '16GB LPDDR5', 'Storage', '512GB SSD', 'Battery', '62Wh about 18 hours'), JSON_ARRAY('laptop', 'lightweight', 'travel'), 'Ships in 2-4 business days with insured delivery.', '2026-06-12 10:00:00.000000'),
