(18, 8, 'NC-WEA-8001', 'pulse-smart-watch-series-6', 'Pulse Smart Watch Series 6', 'Pulse', 'An AMOLED smartwatch with blood oxygen, GPS and a twelve-day battery.', 'Health and fitness tracking, built-in GPS and an always-on AMOLED display in a water-resistant aluminium case.', 4999.00, 7999.00, 88, 10, 4.70, 2511, 'Hot', 1, 1, 'active', 'watch', '#0891B2', JSON_ARRAY('1.43-inch AMOLED', 'SpO2 and heart-rate tracking', 'Built-in GPS', '12-day battery', '50m water resistant'), JSON_OBJECT('Display', '1.43-inch AMOLED 466x466', 'Sensors', 'Heart rate, SpO2, sleep, stress', 'GPS', 'Built-in', 'Battery', '12 days typical', 'Water rating', '5 ATM'), JSON_ARRAY('wearable', 'fitness', 'smartwatch'), 'Ships in 2-4 business days. Free delivery on orders above INR 999.', '2026-06-18 10:00:00.000000'),
